-- Duels, questions ajoutées — fichier 1 sur 10, à exécuter dans l'ordre.
BEGIN;

ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, level = EXCLUDED.level, kind = EXCLUDED.kind, subject = EXCLUDED.subject, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, image_url = EXCLUDED.image_url, image_credit = EXCLUDED.image_credit, slider_min = EXCLUDED.slider_min, slider_max = EXCLUDED.slider_max, slider_step = EXCLUDED.slider_step, correct_value = EXCLUDED.correct_value, unit = EXCLUDED.unit;

-- fr : 1500 questions
ON CONFLICT (question_id, lang) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options,
  unit = EXCLUDED.unit, updated_at = now();

-- es : 1500 questions
ON CONFLICT (question_id, lang) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options,
  unit = EXCLUDED.unit, updated_at = now();

COMMIT;
